FUENTES = {}
FUENTES['test_project_data_idioma.py'] = '#!/usr/bin/env python3\n"""test_project_data_idioma.py — R80f.8 (v81cf13, Chuze): el chequeo de idioma de verificar no marca el VALOR citado del\nplano (nombre propio \'Camino del Rio\') en el bloque PROJECT DATA de Inputs con el rótulo de R80e.121 (\'PROJECT DATA\n(informative - not an input)\'), igual que con el de R80w.44. Sintético; falla con plantilla v81cf10."""\nimport os, sys, tempfile\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport openpyxl\nimport plantilla_excel as P\nd = tempfile.mkdtemp()\nwb = openpyxl.Workbook(); ws = wb.active; ws.title = "Inputs"\nws.cell(40, 1, "PROJECT DATA (informative - not an input)")\nws.cell(41, 1, "Owner / tenant"); ws.cell(41, 2, "Tenant: Chuze Fitness (1011 Camino del Rio South)"); ws.cell(41, 3, "G001")\nms = wb.create_sheet("Material Summary"); ms.append(["x"]); ms.append(["x"])\nms.append(["Material", "Unit", "Net", "Waste %", "Waste", "Purchase", "Selling unit", "Pieces to buy", "Where it comes from", "Yield check (live formula)"])\nwb.create_sheet("Partition Takeoff")\nx = os.path.join(d, "t.xlsx"); wb.save(x)\nerr = P.verificar_excel(x)\nassert not any("Inputs!B41" in e for e in err), [e for e in err if "Inputs" in e]\nprint("test_project_data_idioma OK")\n'
FUENTES['test_markups_vigente_reciente.py'] = '#!/usr/bin/env python3\n"""test_markups_vigente_reciente.py — R80f.8 (v81cf13, Chuze): con dos resúmenes de markups del MISMO canon (una versión\nanterior y la nueva), la compuerta verifica el más reciente, no el primero en orden alfabético. Sintético; falla con\nmarkups_bluebeam v81cf10."""\nimport json, os, sys, tempfile, time\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport markups_bluebeam as MB\nd = tempfile.mkdtemp()\nc = os.path.join(d, "canon.json"); json.dump({"walls": []}, open(c, "w"))\nsha = MB.sha_archivo(c)\njson.dump({"tool": MB.TOOL, "canon_sha": sha, "pdf": "a_FINAL3.pdf"}, open(os.path.join(d, "markups_FINAL3.json"), "w"))\ntime.sleep(0.05)\njson.dump({"tool": MB.TOOL, "canon_sha": sha, "pdf": "a_FINAL4.pdf"}, open(os.path.join(d, "markups_FINAL4.json"), "w"))\nos.utime(os.path.join(d, "markups_FINAL3.json"), (1, 1))\nr, m = MB.resumen_vigente([d], c)\nassert r and r["pdf"].endswith("a_FINAL4.pdf"), (r, m)\nprint("test_markups_vigente_reciente OK")\n'
FUENTES['test_markups_be117.py'] = '#!/usr/bin/env python3\n"""test_markups_be117.py — R80f.9 / R80f.10 (BE-117): (1) un tramo recto cuya banda difiere del LF en menos de TOL_PT\nse dibuja con el largo del LF (Bluebeam Length = Excel); (2) el SF de Contents = board SF de la fila (board_out.json\njunto al canon); (3) DETAIL de un type con guion completo (A2-3D/A301); (4) leyenda por hoja en el orden del schedule\n(constants.type_order). Sintético; falla con markups_bluebeam v81cf10."""\nimport json, math, os, sys, tempfile\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport markups_bluebeam as MB\nq = MB.ajustar_a_lf([(0, 0), (52.0, 0)], 2.96, 18)\nassert abs(math.dist(*q) - 2.96 * 18) < 1e-6\nassert MB.ajustar_a_lf([(0, 0), (100.0, 0)], 2.96, 18) == [(0, 0), (100.0, 0)]     # diferencia grande: no se toca\nassert MB.cita({"detail": "TYPE A2-3D/A301"}) == "A2-3D/A301"\nd = tempfile.mkdtemp(); os.makedirs(os.path.join(d, "out"))\njson.dump({"caras": [{"wall": "W1", "sf": 100.0}, {"wall": "W1", "sf": 50.5}]}, open(os.path.join(d, "out", "board_out.json"), "w"))\nc = os.path.join(d, "canon.json"); json.dump({"walls": []}, open(c, "w"))\nMB.cargar_board(c)\nassert MB.BOARD_SF == {"W1": 150.5}\nassert "150.50 SF board" in MB.contenido({"id": "W1", "length_ft": 10, "height_ft": 12, "tag": "A3C", "detail": "TYPE A3C/A301"})\no = MB.orden_types({"constants": {"type_order": {"value": ["B1", "A9"]}}}, ["A9", "OTHER FRAMING", "B1"])\nassert o == ["B1", "A9", "OTHER FRAMING"], o\nassert hasattr(MB, "leyendas_por_hoja")\nprint("test_markups_be117 OK")\n'
FUENTES['test_auditoria_entrega.py'] = '#!/usr/bin/env python3\n"""test_auditoria_entrega.py — R80f.11 / BE-117: auditoria_entrega.py compara cada annot del PDF de markups con su\nfila de la Partition Takeoff (TYPE · LF · H · SF · DETAIL · id), la escala /Measure con el rótulo SCALE impreso y el\nLength con el LF; reporta la annot cuyo SF, escala o Length no coincide con el Excel. Sintético; la tool no existe\nen v81cf10."""\nimport json, os, sys, tempfile\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport openpyxl, pymupdf as fitz\nimport markups_bluebeam as MB\nimport auditoria_entrega as AE\nd = tempfile.mkdtemp()\ndoc = fitz.open(); p = doc.new_page(width=1000, height=700)\np.insert_text((50, 650), "FLOOR PLAN  SCALE: 1/4\\" = 1\'-0\\"", fontsize=10)\ndef annot(nm, pts, content):\n    a = p.add_polyline_annot(pts); a.set_info(title="Take-off", subject="A3C", content=content); a.update()\n    MB._nm(doc, a, "TO-" + nm); MB._measure(doc, a, 18.0)\nannot("W1", [(100, 100), (100 + 18 * 10, 100)], "A3C · 10.00 LF · H 12\'-0\\" · 240.0 SF board · A3C/A301 · W1")\nannot("W2", [(100, 200), (100 + 18 * 11, 200)], "A3C · 10.00 LF · H 12\'-0\\" · 999.0 SF board · A3C/A301 · W2")\npdf = os.path.join(d, "m.pdf"); doc.save(pdf)\nwb = openpyxl.Workbook(); wb.active.title = "Inputs"\nws = wb.create_sheet("Partition Takeoff"); ws.append(["t"]); ws.append(["t"]); ws.append([]); ws.append(["h"])\nws.append(["TYPE A3C"])\nws.append(["A3C  #W1  -  x", "W1", 10.0, 12.0, 1, "3-5/8\\"", 16, 240.0, "x", "TYPE A3C/A301", "[DERIVED]"])\nws.append(["A3C  #W2  -  x", "W2", 10.0, 12.0, 1, "3-5/8\\"", 16, 240.0, "x", "TYPE A3C/A301", "[DERIVED]"])\nws.append([None, "SUBTOTAL TYPE A3C", 20.0]); ws.append([None, "TOTAL - PARTITIONS (GRAND TOTAL)", 20.0])\nfor n in ("Material Summary", "Pending Items", "Review Items", "Scope Checklist"):\n    wb.create_sheet(n)\nx = os.path.join(d, "t.xlsx"); wb.save(x)\nc = os.path.join(d, "canon.json"); json.dump({"walls": [{"id": "W1", "sheet": "1"}, {"id": "W2", "sheet": "1"}]}, open(c, "w"))\nres = AE.auditar(x, pdf, c)\nbad = {(r[0][:1], r[1].split()[0]) for r in res if not r[2]}\nassert ("1", "W2") in bad and ("3", "W2") in bad, bad          # SF distinto y Length 11 ft vs LF 10\nassert ("1", "W1") not in bad and ("2", "W1") not in bad and ("3", "W1") not in bad, bad\nprint("test_auditoria_entrega OK")\n'

FUENTES['test_rcp_multihoja.py'] = '#!/usr/bin/env python3\n"""test_rcp_multihoja.py — R80f.13 / R80f.14 / R80f.15 (Chuze FINAL5): (1) markups_rcp.py pone el polígono de cada\nceiling en SU hoja (ceilings[].sheet; varias hojas de RCP), con NM / ID = ceilings[].id, el tag del cielo en el\nContents y sin clusters de bracing cuando constants.ceiling_lateral_bracing = false; (2) verificar_markups_excel\nencuentra el PDF \'Markups\' (mayúscula) junto al Excel; (3) auditoria_entrega cuadra un área contra el desglose\n\'ID SF\' del Material Summary y su área dibujada. Sintético; falla con las tools v81cf17."""\nimport json, os, sys, tempfile\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport pymupdf as fitz\nimport markups_rcp as MR\nimport verificar_markups_excel as VME\nd = tempfile.mkdtemp()\ndoc = fitz.open()\nfor lab in ("X1.A", "X2.A"):\n    p = doc.new_page(width=800, height=600)\n    p.insert_text((700, 580), lab, fontsize=12)\ndoc.set_page_labels([{"startpage": 0, "prefix": "X1.A", "style": "", "firstpagenum": 1},\n                     {"startpage": 1, "prefix": "X2.A", "style": "", "firstpagenum": 1}])\npin = os.path.join(d, "in.pdf"); doc.save(pin)\ncanon = {"constants": {"plan_scale_by_sheet": {"X1.A": {"value": 18.0, "source": "t"}, "X2.A": {"value": 18.0, "source": "t"}},\n                       "ceiling_lateral_bracing": {"value": False, "source": "t"}},\n         "ceilings": [{"id": "CLG-1", "room": "R1", "sheet": "X1.A", "area_sf": 4.0, "board": "5/8 type X", "height_ft": 9,\n                       "detail": "Z-9/X121", "ceiling_tag": "Z-9", "system": "usg_grid", "ns_ft": 20, "ew_ft": 20},\n                      {"id": "CLG-2", "room": "R2", "sheet": "X2.A", "area_sf": 4.0, "board": "5/8 type X", "height_ft": 9,\n                       "detail": "Z-9/X121", "system": "usg_grid", "ns_ft": 20, "ew_ft": 20}]}\ncp = os.path.join(d, "canon.json"); json.dump(canon, open(cp, "w"))\nsq = [[100, 100], [136, 100], [136, 136], [100, 136]]\npp = os.path.join(d, "polys.json"); json.dump([{"id": "CLG-1", "polygon": sq}, {"id": "CLG-2", "polygon": sq}], open(pp, "w"))\nout = os.path.join(d, "Proj_Markups_X.pdf")\nassert MR.escribir(pin, cp, pp, out, os.path.join(d, "png")) == 0\nr = fitz.open(out)\nan = [(i, a.info.get("id"), a.info.get("content")) for i in range(r.page_count) for a in r[i].annots()]\nassert {(0, "TO-CLG-1"), (1, "TO-CLG-2")} <= {(i, n) for i, n, _ in an}, an\nassert any("GWB CEILING Z-9" in c for _, _, c in an)\nassert not r[0].get_drawings() or not any(dr.get("fill") == (0.85, 0.1, 0.55) for dr in r[0].get_drawings())\nassert sorted(os.listdir(os.path.join(d, "png"))) == ["X1.A_rcp_markups.png", "X2.A_rcp_markups.png"]\nxl = os.path.join(d, "Proj_Takeoff_X.xlsx"); open(xl, "w").close()\nassert VME.buscar_pdf(d, excel=xl) == os.path.abspath(out)\nimport auditoria_entrega as AE\nsrc = open(AE.__file__, encoding="utf-8").read()\nassert "1 area annot = Excel breakdown" in src and "3 Area vs SF" in src\nprint("test_rcp_multihoja OK")\n'
FUENTES['test_rcp_hatch.py'] = '#!/usr/bin/env python3\n"""test_rcp_hatch.py — R80f.16: el polígono de un cielo GWB sigue al HATCH (el cielo = solo el área con hatch,\nlimitada por las caras): una parte del polígono sin trazos del hatch que toca su borde (caja blanca, rincón fuera del\nmuro en L) se reporta y markups_rcp sale rc 1; un hueco interior chico (difusor / fan) es una abertura y no se reporta;\nel polígono que excluye la parte sin hatch pasa. Sintético; falla con markups_rcp v81cf18 (antes de R80f.16)."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport pymupdf as fitz\nimport markups_rcp as MR\ndoc = fitz.open(); p = doc.new_page(width=400, height=300)\ng = (0.5, 0.5, 0.5)\nsh = p.new_shape()\nfor x in range(20, 220, 4):          # hatch 20..220 x 20..120, salvo la caja 160..220 x 20..70 y un hueco 80..90 x 60..70\n    for y in range(20, 120, 4):\n        if (160 <= x < 220 and 20 <= y < 70) or (80 <= x < 90 and 60 <= y < 70):\n            continue\n        sh.draw_line((x, y), (x + 1.5, y + 1.0))\nsh.finish(color=g, width=0.24); sh.commit()\nfull = [(20, 20), (220, 20), (220, 120), (20, 120)]\nr = MR.sin_hatch(p, full, g)\nassert len(r) == 1 and r[0][1][0] >= 155 and r[0][0] > 1500, r\nok = [(20, 20), (160, 20), (160, 70), (220, 70), (220, 120), (20, 120)]\nassert MR.sin_hatch(p, ok, g) == [], MR.sin_hatch(p, ok, g)\nprint("test_rcp_hatch OK")\n'

# v81cf24: + test_mr_typex.py (R80w.45) y test_coord_rango.py (R80w.19) de la rama Chuze, unidos aquí sin cambios (límite de 200 archivos)
FUENTES['test_mr_typex.py'] = '#!/usr/bin/env python3\n"""test_mr_typex.py — R80w.45: un renglón "5/8 Type X MR (moisture resistant)" (MR con núcleo Type X, como lo pide el\nspec) es de la familia MR, no de Type X; Type X y Type X W.R. siguen en las suyas. Sintético; falla con familias v80w.44."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport familias as F\nassert F.familia(\'5/8" gypsum board, Type X MR (MOISTURE RESISTANT, 09 29 00 2.3.E)\', "sf") == \'5/8" gyp MOISTURE RESISTANT\'\nassert F.familia(\'5/8" gypsum board, Type X\', "sf") == \'5/8" gyp board Type X\'\nassert F.familia(\'5/8" gypsum board, Type X W.R. (water resistant)\', "sf") == \'5/8" gyp Type X W.R.\'\nprint("test_mr_typex OK")\n'
FUENTES['test_coord_rango.py'] = '#!/usr/bin/env python3\n"""test_coord_rango.py — R80w.19: una coordenada con rango ("y 1813-1875", "x 10.5-20") en un texto del Excel no deja una\n"y" suelta que el chequeo de idioma lea como español. Sintético; falla con plantilla_excel v80v. Protección: una "y"\nespañola de verdad sigue detectada."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport plantilla_excel as P\nassert P.es_texto_es("Room X1 sink area (W face of V, y 1813-1875) 1.76 x 12.08 ft") == [], \\\n    P.es_texto_es("Room X1 sink area (W face of V, y 1813-1875) 1.76 x 12.08 ft")\nassert P.es_texto_es("north face (x 10.5-20.25 pt) of the wall") == []\nassert P.es_texto_es("la cara norte y la cara sur del muro"), "español real no detectado (protección)"\nprint("test_coord_rango OK")\n'

# Chuze FINAL6 (R80f.29–R80f.34 / BE-134) tests embebidos: test_sf_parte · test_altura_regla_impresa · test_tipos_schedule · test_board_y_capas · test_gauge_min_y_oc · test_compuerta_pdf_entregado · test_alturas_exactas ( AE.exacta ) · test_r80f21
FUENTES['test_chuze_r80f17_19.py'] = '#!/usr/bin/env python3\n"""R80f.29-19 (Chuze FINAL6, 3-nov-2026): contradicciones entre herramientas que encontró compuerta_entrega v1.\nR80f.29 revision_markups: etiqueta \'SF board\' (BE-117) se compara con Board (SF) del Excel, no con LF x H; la altura\n         impresa suma los incrementos impresos de la cadena (\'10\'-0\\" AFF + 6\\" (SKILL §7) = 10.5\').\nR80f.30 revision_materiales: texto de board del schedule = principal + condicionales por cuarto; board más pesado que el\n         impreso = AMBER; gauge MIN.; O.C. más cerrado con fuente = AMBER; capas no impresas no se exigen; cara END no\n         es un lado; MR del canon = renglón Type X MR.\nR80f.31 compuerta_entrega: reglas.py revisa el PDF de markups ENTREGADO (TAKEOFF_MARKUPS_PDF)."""\nimport os\nimport sys\n\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport revision_markups as RM          # noqa: E402\nimport revision_materiales as RV       # noqa: E402\n\nTXT = (\'5/8" GYP BD, PROVIDE 5/8" CEMENT BACKER BOARD BEHIND ALL TILE AND 5/8" MOISTURE RESISTANT GYP AT ALL "WET" \'\n       \'ROOMS. - BOTH SIDES. AT POOL/SPA ROOMS USE DENSARMOR PLUS 5/8" SHEETING FULL HEIGHT.\')\n\n\ndef test_sf_parte():\n    p = [x.strip() for x in "A3C · 10.00 LF · H 10\'-0\\" · 200.00 SF board · C/A301 · W-1".split("·")]\n    assert RM._sf_parte(p) == (200.0, True)\n    p = [x.strip() for x in "EX · 9.64 LF · H 22\'-10\\" · 2 face(s) · 440.16 SF board · D0.07/AD101 · EX-04A".split("·")]\n    assert RM._sf_parte(p) == (440.16, True)\n    p = [x.strip() for x in "A3C · 10.00 LF · H 10\'-0\\" · 100.0 SF · C/A301 · W-1".split("·")]\n    assert RM._sf_parte(p) == (100.0, False)\n\n\ndef test_altura_regla_impresa():\n    h, r, _ = RM.altura_impresa("head C: ceilings 10\'-0\\" AFF C-1 (A435 RCP) + 6\\" (SKILL §7) = 10.5; zone to deck")\n    assert h == 10.5 and r in ("printed dimension + printed rule", "derived: printed operands, operation re-done by program"), (h, r)\n    h, r, _ = RM.altura_impresa("stud to 14\'-5\\" = 14.42 (CONFIRMED); rest + 6\\" = 12.58")\n    assert abs(h - 14.4167) < 0.01, (h, r)    # no suma el incremento escrito despues del igual\n\n\ndef test_tipos_schedule():\n    assert RV.tipos_schedule(TXT) == ("REG", {"CEMENT", "WR", "GLASSMAT"})\n    assert RV.tipos_schedule(\'5/8" TYPE X GYP BD\') == ("X", set())\n\n\ndef _ficha(**k):\n    f = {"faces": [{"side": "each side", "layers": None, "board": TXT}], "sources": {"board": "A/A301", "stud": "A2/A301"}}\n    f.update(k)\n    return f\n\n\ndef test_board_y_capas():\n    cw = {"W-1": {"faces": [{"side": "A", "board": "5/8 type X", "layers": 1, "height_ft": 10},\n                            {"side": "B", "board": "5/8 MR", "layers": 1, "height_ft": 10},\n                            {"side": "END", "board": "5/8 type X", "layers": 1, "height_ft": 10}], "oc_source": "S100 table"}}\n    filas = [{"type": "A3C", "wall": "W-1", "stud": \'3-5/8" 20 ga\', "oc": 16, "h": 10.0}]\n    r = RV.comparar_type("A3C", _ficha(), filas, cw)\n    assert r["verdict"] != "RED", r["checks"]\n    assert any(c["status"] == "AMBER" and "heavier" in c["note"] for c in r["checks"]), r["checks"]\n\n\ndef test_gauge_min_y_oc():\n    cw = {"W-2": {"faces": [{"side": "A", "board": "5/8 type X", "layers": 1, "height_ft": 20},\n                            {"side": "B", "board": "5/8 type X", "layers": 1, "height_ft": 20}],\n                  "oc_source": "estimator decision 2026-11-02 (RFI-S01 option A)", "gauge_source": "RFI-S01 option A"}}\n    filas = [{"type": "A2-3D", "wall": "W-2", "stud": \'3-5/8" 16 ga 362S162-54 @ 12" O.C.\', "oc": 12, "h": 20.0}]\n    r = RV.comparar_type("A2-3D", _ficha(gauge_ga=25, oc_in=16), filas, cw)\n    est = {c["field"]: c["status"] for c in r["checks"]}\n    assert est["gauge"] == "AMBER" and est["stud O.C."] == "AMBER", r["checks"]\n    filas[0]["stud"], filas[0]["oc"] = \'3-5/8" 30 ga\', 24          # más liviano / más abierto = RED\n    r = RV.comparar_type("A2-3D", _ficha(gauge_ga=25, oc_in=16), filas, cw)\n    est = {c["field"]: c["status"] for c in r["checks"]}\n    assert est["gauge"] == "RED" and est["stud O.C."] == "RED", r["checks"]\n\n\ndef test_compuerta_pdf_entregado():\n    src = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "compuerta_entrega.py"), encoding="utf-8").read()\n    assert \'env["TAKEOFF_MARKUPS_PDF"] = c.markups\' in src\n\n\nif __name__ == "__main__":\n    for k, f in list(globals().items()):\n        if k.startswith("test_"):\n            f()\n            print("ok", k)\n    print("test_chuze_r80f17_19 OK")\n'
FUENTES['test_alturas_exactas.py'] = '#!/usr/bin/env python3\n"""R80f.32: alturas redondeadas del canon -> ft-in exactas."""\nimport os\nimport sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport alturas_exactas as AE  # noqa: E402\n\nassert AE.exacta(22.83) == 22.8333 and AE.exacta(14.42) == 14.4167 and AE.exacta(12.083) == 12.0833\nassert AE.exacta(12.58) == 12.5833 and AE.exacta(7.17) == 7.1667\nassert AE.exacta(10.5) is None and AE.exacta(22.8333) is None and AE.exacta(9.0) is None\nc = {"walls": [{"height_ft": 22.83, "faces": [{"height_ft": 22.83}], "openings": [{"head_ft": 7.17}], "length_ft": 12.34}]}\nch = AE.corregir(c)\nassert len(ch) == 3 and c["walls"][0]["length_ft"] == 12.34 and c["walls"][0]["faces"][0]["height_ft"] == 22.8333\nprint("test_alturas_exactas OK")\n'
FUENTES['test_r80f21.py'] = '#!/usr/bin/env python3\n"""test_r80f21 — R80f.33 (Chuze FINAL6): (1) bitacora._vigente acepta una COPIA idéntica (mismo nombre, mismo sha256) del\narchivo que corrió la tool (la compuerta revisa la copia de FINAL_FOR_REVIEW*/Take-off/); un archivo distinto no;\n(2) revision_markups._mismo_bloque: \'OTHER FRAMING - SOFFIT SIDE\' / \'BOARD ONLY - NO FRAMING\' = su bloque del Excel;\n(3) revision_materiales: el driver impreso redondeado (\'65,378 SF\') se acepta con media unidad de su precisión."""\nimport os, sys, tempfile, shutil\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport bitacora as B\nimport revision_markups as RM\nd = tempfile.mkdtemp()\na = os.path.join(d, "x", "T.xlsx"); os.makedirs(os.path.dirname(a)); open(a, "wb").write(b"abc")\nb = os.path.join(d, "y", "T.xlsx"); os.makedirs(os.path.dirname(b)); shutil.copy(a, b)\nr = {"hashes": {a: B.sha(a)}}\nassert B._vigente(r, b)\nopen(b, "wb").write(b"abd")\nassert not B._vigente(r, b)\nassert RM._mismo_bloque("OTHER FRAMING - SOFFIT SIDE", "OTHER FRAMING")\nassert RM._mismo_bloque("BOARD ONLY - NO FRAMING", "BOARD ONLY - EXISTING OR WOOD-FRAMED WALLS (FRAMING NOT IN SCOPE)")\nassert not RM._mismo_bloque("A3C", "OTHER FRAMING")\nsrc = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "revision_materiales.py"), encoding="utf-8").read()\nassert "0.5 * 10 ** -dec" in src\nprint("test_r80f21 OK")\n'

# Chuze FINAL6 gate v25 (R80f.35 / R80f.36 / BE-135) tests embebidos: test_hoja_etiqueta · test_norm_hoja_punto · test_be102_falsos · test_cita_posesivo · test_be20_ids · test_be89_esquinas · test_cielo_impreso (test_r80f35_36.py)
FUENTES['test_r80f35_36.py'] = '#!/usr/bin/env python3\n"""R80f.35 / R80f.36 (Chuze FINAL6 gate v25, BE-135): set_texto labels with a letter suffix (A421.B), sheet ids with / without\nthe dot (A503.C = A503C) and the checker false positives of the delivery gate. Each case: the original error -> FAIL, fixed -> PASS."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "runner"))\nimport compuerta_entrega as CE\nimport chequeos_biblioteca as CB\nimport completitud\n# test_hoja_etiqueta: page label \'A421.B-RECEPTION ELEVATIONS\' -> A421.B (v24 fell back to title-block noise: \'p24\', \'P9\')\nassert CE.hoja_de_etiqueta("A421.B-RECEPTION ELEVATIONS") == "A421.B"\nassert CE.hoja_de_etiqueta("A503.C-MILLWORK & MISC. DETAILS") == "A503.C"\nassert CE.hoja_de_etiqueta("A432-MACHINE") == "A432" and CE.hoja_de_etiqueta("A1.11") == "A1.11"\nassert CE.hoja_de_etiqueta("") == "" and CE.hoja_de_etiqueta("COVER") == ""\n# test_norm_hoja_punto: A503.C and the printed \'4/A503C\' are the same sheet; RX_DET keeps the dot suffix\nassert CB.norm_hoja("A503.C") == CB.norm_hoja("A503C") == "A503C"\nassert ("12", "A503.C") in CB.RX_DET.findall("see 12/A503.C") and ("4", "A503C") in CB.CALLOUT.findall("REF: DETAIL 4/A503C FOR")\nhojas = {"A421": "REF: DETAIL 4/A503C FOR MOUNTING", "A503.C": "4\\nDRY VANITY SECTION\\n9\\nCEILING MOUNTED TV DETAIL"}\ncanon = {"walls": [{"id": "W1", "sheet": "A421", "tag": "A6D"}]}\nr = CB.ce_callouts(CB.B(canon=canon, hojas=hojas, celdas=[], set_meta={"burbujas": {}}))\nassert r[0] == "FAIL" and not any("no existe" in e for e in r[1]), r\nr = CB.ce_callouts(CB.B(canon=canon, hojas=hojas, celdas=[], set_meta={"burbujas": {}}, no_aplican={"A503.C": {"4": "millwork, TV detail is 9/A503.C by G.C."}}))\nassert r[0] == "PASS", r\n# test_be102_falsos: \'-15 / A6C\', \'RFI-06 / RFI-30\', \'C-1 / C-2\', keynotes \'A1.11/A1.13\', types \'A6D / X6D\' are not N/SHEET\ntxt = "A-A421-15 / A6C; RFI-06 / RFI-30; C-1 / C-2 / C-3; A101 A1.11/A1.13; A6D / X6D 20 ga; 05 40 00 3.5.G / S100"\nmk = lambda t: CB.B(canon={"walls": [{"id": "W", "tag": "A6D"}, {"id": "X", "tag": "X6D"}]}, hojas={"A301": "", "S100": ""},\n                    celdas=[("Scope Checklist", "D1", t)])\nassert CB.be_102(mk(txt))[0] == "PASS", CB.be_102(mk(txt))\nassert CB.be_102(mk("see 10/A505"))[0] == "FAIL"\n# test_cita_posesivo: MEN\'S is not an opening quote; the misquoted text still fails\nb = lambda t: CB.B(canon={}, hojas={"A602": "STEEL HEADER @ HEAD\\nLOCATIONS - REF: STRUCT."}, celdas=[("Material Summary", "I1", t)])\nassert CB.be_12(b("905 MEN\'S LOCKER (C-3 12\'-1\\" existing) \'STEEL HEADER @ HEAD LOCATIONS - REF: STRUCT.\'"))[0] == "PASS"\nassert CB.be_12(b("6/A602 \'STEEL HEADER - REF: STRUCT.\'"))[0] == "FAIL"\n# test_be20_ids: soffit studs named by Wall ID in the stud breakdown\nss = {"walls": [{"id": "A-A422.A-1", "element": "soffit_side"}]}\nms = lambda s: [{"fila": 4, "material": "6\\" metal stud", "net": 10, "fuente": s}, {"fila": 5, "material": "Ceiling / soffit track", "net": 5, "fuente": "x"}]\nassert CB.be_20(CB.B(canon=ss, ms=ms("Breakdown: A-A421-6 50")))[0] == "FAIL"\nassert CB.be_20(CB.B(canon=ss, ms=ms("Breakdown: A-A421-6 50 + A-A422.A-1 114.67")))[0] == "PASS"\n# test_be89_esquinas: 3 of 4 nodes free; every geometric corner of esquinas.py has its L node -> PASS; a corner without node -> FAIL\nns = [{"id": "N1", "kind": "L", "walls": ["W1", "W2"]}] + [{"id": f"F{i}", "kind": "free", "wall": "W1"} for i in range(5)]\nassert CB.be_89(CB.B(canon={"nodes": ns}))[0] == "FAIL"\nassert CB.be_89(CB.B(canon={"nodes": ns}, esquinas={"fallas": [], "esquinas": [{"walls": ["W2", "W1"]}]}))[0] == "PASS"\nassert CB.be_89(CB.B(canon={"nodes": ns}, esquinas={"fallas": [], "esquinas": [{"walls": ["W3", "W1"]}]}))[0] == "FAIL"\n# test_cielo_impreso: a face that stops at its printed ceiling (C-12 ACT 14\'-0" AFF) vs a GWB box of the same room at 9\'-0"\ncn = {"ceilings": [{"room": "905 box", "height_ft": 9.0}],\n      "walls": [{"id": "W", "faces": [{"room": "Space 905", "height_ft": 14.0, "height_source": "C-12 ACT 14\'-0\\" AFF (A423.A)"}]}]}\nassert completitud.caras_sobre_ceiling(cn) == []\ncn["walls"][0]["faces"][0].update(height_ft=22.8333, height_source="B.O. DECK 22\'-10\\" (A423.B)")\nassert len(completitud.caras_sobre_ceiling(cn)) == 1\nprint("test_r80f35_36 OK")\n'

# Chuze FINAL6 gate v27 (R80f.37 / R80f.38 / BE-136) tests embebidos: test_tramos_rectos · test_u120_tramos · test_vs13_tramos · test_u115_keynote · test_u116_review_item · test_u119_falsos · test_u121_label · test_u117_wrap_desc · test_imagen_revision (test_r80f37_38.py)
FUENTES['test_r80f37_38.py'] = '#!/usr/bin/env python3\n"""R80f.37 / R80f.38 (Chuze FINAL6 gate v27, BE-136): one straight axis per markup (U-120) with the legs summed back to the\nExcel row, and the day-1 checker false positives (U-115 keynote N/SHEET, U-116 Review Item, U-117 column wraps and canon\ntags_descartados, U-119 file names / coordinates / proper names / EL.+, U-121 Page Label \'A421.A\', BE-VS-13 legs,\nR80e.84 Review Items Image column). Each case: the original error -> FAIL, fixed -> PASS."""\nimport os, sys, tempfile\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport chequeos_biblioteca as CB\nimport idioma_es\nimport markups_bluebeam as MB\nimport plantilla_excel as PE\n# test_tramos_rectos: a 3-sided wrap path = 3 legs; a straight run = 1; an arc (short segments) is not cut\nU = [(0, 0), (0, 16), (54, 16), (54, 0)]\nassert len(MB.tramos_rectos(U)) == 3 and MB.tramos_rectos([(0, 0), (90, 0)]) == [[(0, 0), (90, 0)]]\narc = [(100 * __import__("math").cos(a / 50), 100 * __import__("math").sin(a / 50)) for a in range(0, 60)]\nassert len(MB.tramos_rectos(arc)) == 1\nassert MB.repartir(4.77, [15.9, 54, 15.9], 3) == [0.884, 3.002, 0.884] or abs(sum(MB.repartir(4.77, [15.9, 54, 15.9], 3)) - 4.77) < 1e-9\n# test_u120_tramos: the bent polyline fails U-120, its legs pass\nan = lambda vs: [{"label": "A421", "contents": "C3C · 4.77 LF · H 10\'-6\\" · 47.70 SF board · C3C/A301 · W1", "subject": "C3C",\n                  "tipo": "PolyLine", "verts": vs}]\nassert CB.u_120(CB.B(canon={"walls": [{"id": "W1"}]}, annots=an(U)))[0] == "FAIL"\nassert CB.u_120(CB.B(canon={"walls": [{"id": "W1"}]}, annots=an(U[:2]) + an(U[1:3]) + an(U[2:])))[0] == "PASS"\n# test_vs13_tramos: BE-VS-13 sums the SF of the legs of one wall against its Excel row\npt = [{"fila": 6, "wall": "W1", "lf": 4.77, "h": 10.5, "board": 47.7}]\nlegs = [{"label": "A421", "contents": f"C3C · {l} LF · H 10\'-6\\" · {s} SF board · C3C/A301 · W1", "subject": "C3C"}\n        for l, s in ((0.885, 9.29), (3.0, 30.0), (0.885, 8.41))]\nassert CB.be_vs_13(CB.B(canon={}, pt=pt, annots=legs))[0] == "PASS"\nassert CB.be_vs_13(CB.B(canon={}, pt=pt, annots=legs[:1]))[0] == "FAIL"\n# test_u115_keynote: \'D0.07/AD101\' is an N/SHEET; \'TYPE A2-3D/A301\' is not\npt2 = lambda src: [{"fila": 7, "wall": "EX-01", "lf": 10.0, "board": 20.0, "source": src}]\nassert CB.u_115(CB.B(canon={}, pt=pt2("D0.07/AD101 - AD101 keynote D0.07 \'EXISTING WALL TO REMAIN\'")))[0] == "PASS"\nassert CB.u_115(CB.B(canon={}, pt=pt2("TYPE A2-3D/A301")))[0] == "FAIL"\n# test_u116_review_item: a \'not printed\' that points to its Review Item (alternatives + delta) is not silent\ncel = lambda t: CB.B(canon={}, celdas=[("Review Items", "D3", t)])\nassert CB.u_116(cel("ceiling height not printed; loaded 8\'-0\\""))[0] == "FAIL"\nassert CB.u_116(cel("ceiling height not printed (this Review Item: alternatives and delta); loaded 8\'-0\\""))[0] == "PASS"\n# test_u119_falsos: file name, plan coordinates, proper names and \'EL.+\' are not Spanish; real Spanish still is\nfor t in ("Bid set: bidset_SIN_MARKUPS.pdf (Chuze Fitness)", "Tenant: Chuze (1011 Camino del Rio South, Suite 350)",\n          "Sink area (W face of V, y 1813-1875) 1.76 x 12.08 ft", "wall line y1622 over the shower area"):\n    assert idioma_es.es_espanol(t) == [], t\nassert idioma_es.es_espanol("el muro y la altura del cielo")\nassert CB.u_119(CB.B(canon={}, celdas=[("Review Items", "D3", "board to 2/A425.B \'EL.+ 8\'-0\\"\' of the strip")]))[0] == "PASS"\n# test_u121_label: Page Label \'A421.A\' is a sheet number\nmk = lambda lab: CB.B(canon={}, annots=[{"label": lab, "subject": "OTHER FRAMING - SOFFIT SIDE", "contents": "x", "tipo": "PolyLine",\n                                          "measure": True, "depth": 1.5, "nm": "TO-S1"}])\nassert CB.u_121(mk("A421.A"))[0] == "PASS" and CB.u_121(mk("p23"))[0] == "FAIL"\n# test_u117_wrap_desc: a column_wrap tag and a canon discard with motive count; a discard without motive does not\ninv = {"ocurrencias": {"partition_tag": [{"id": "PT0001", "type": "C3C", "sheet": "A421", "png": "x.png", "png_verificado": True},\n                                         {"id": "PT0002", "type": "C3C", "sheet": "A421", "png": "x.png", "png_verificado": True}]}}\nd = tempfile.mkdtemp()\nfrom PIL import Image, ImageDraw\nim = Image.new("RGB", (60, 60), "white"); ImageDraw.Draw(im).ellipse([5, 5, 55, 55], outline=(255, 0, 0), width=4); im.save(os.path.join(d, "x.png"))\nw = [{"id": "W1", "element": "column_wrap", "tag": "C3C", "tag_ids": ["PT0001"]}, {"id": "W2", "element": "wall", "tag": "C3C"}]\nb = lambda desc: CB.B(canon={"walls": w, "tags_descartados": desc}, inv_full=inv, raiz=d)\nassert CB.u_117(b([]))[0] == "FAIL"\nassert CB.u_117(b([{"id": "PT0002", "motivo": "same wall as A422, counted there", "imagen": "x.png"}]))[0] == "PASS", CB.u_117(b([{"id": "PT0002", "motivo": "same wall as A422, counted there", "imagen": "x.png"}]))\n# test_imagen_revision: the Review Items \'Image\' column may name the image; a file name elsewhere is still internal text\nimport openpyxl\nwb = openpyxl.Workbook(); ws = wb.active; ws.title = PE.HOJA_REVISAR\nws.append(["1 questions in total"]); ws.append(["#", "Phase", "Type / order", "Item", "Sheet + detail", "Image"])\nws.append(["1/1", "Detail", 1, "Confirm X", "A301", "rev_A301_A2.png"])\nassert not PE.verificar_texto_cliente(wb)\nws["D3"] = "see rev_A301_A2.png"\nassert PE.verificar_texto_cliente(wb)\nprint("test_r80f37_38 OK")\n'

# Chuze FINAL6 gate v30 (R80f.39 / BE-137) test embebido: test_u034_misma_cosa · test_u034_hoja_leida (test_r80f39.py)
FUENTES['test_r80f39.py'] = '#!/usr/bin/env python3\n"""R80f.39 (Chuze FINAL6 gate v30, BE-137): U-034 compares the two readings element by element, not label by label: a\ncolumn_wrap / pier of one reading that the other reads as a wall of the same schedule tag on the same sheet, and a keynote\npseudo-tag (\'A2.25-INFILL\') that the other reading names on the same sheet, are the same element. A soffit_side the other\nreading does not have is still missing. Original error -> FAIL, fixed -> PASS."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport chequeos_biblioteca as CB\nA = {"walls": [{"id": "A1", "tag": "C3C", "element": "column_wrap", "sheet": "A421"},\n               {"id": "A2", "tag": "A2.25-INFILL", "element": "wall", "sheet": "A434"},\n               {"id": "A3", "tag": "A6D", "element": "wall", "sheet": "A421"}]}\nB = {"walls": [{"id": "B1", "tag": "C3C", "element": "wall", "sheet": "A421"},\n               {"id": "B2", "tag": "A6D", "element": "wall", "sheet": "A434", "location": "infill of door opening (keynote A2.25)"},\n               {"id": "B3", "tag": "A6D", "element": "wall", "sheet": "A421"}]}\n# test_u034_misma_cosa\nassert CB._misma_cosa("column_wrap", B, A) and CB._misma_cosa("A2.25-INFILL", B, A)\nr = CB.u_034(CB.B(canon={}, canon_a=A, canon_b=B))\nassert r[0] == "PASS", r\n# a soffit_side only in A is still a hole in B\nA2 = {"walls": A["walls"] + [{"id": "A4", "tag": "SOFFIT", "element": "soffit_side", "sheet": "A421"}]}\nassert CB.u_034(CB.B(canon={}, canon_a=A2, canon_b=B))[0] == "FAIL"\n# a column_wrap whose tag the other reading does not have on that sheet is not excused\nB2 = {"walls": [w for w in B["walls"] if w["id"] != "B1"]}\nassert not CB._misma_cosa("column_wrap", B2, A)\nprint("test_r80f39 OK")\n# test_u034_hoja_leida: a sheet the reading declares read, with every inventory tag of that sheet disposed, is not "missing"\ninv = {"ocurrencias": {"partition_tag": [{"id": "PT0001", "type": "A6D", "sheet": "A101"}]}}\nA3 = {"walls": A["walls"] + [{"id": "A5", "tag": "A6D", "element": "wall", "sheet": "A101"}]}\nB3 = dict(B, sheets_read=["A421", "A434", "A101"], tags_descartados=[{"id": "PT0001", "motivo": "shown on enlarged plan A421 (counted there)"}])\nassert CB._hoja_leida_vacia(CB.B(canon={}, inv_full=inv), B3, "A101")\nassert CB.u_034(CB.B(canon={}, canon_a=A3, canon_b=B3, inv_full=inv))[0] == "PASS"\nB4 = dict(B3, tags_descartados=[])\nassert CB.u_034(CB.B(canon={}, canon_a=A3, canon_b=B4, inv_full=inv))[0] == "FAIL"\nprint("test_u034_hoja_leida OK")\n'

# U-127 / BE-138 (Chuze, 4-nov) CB_BOTH_SIDES: test_both_sides · both_sides
FUENTES['test_both_sides.py'] = '#!/usr/bin/env python3\n"""test_both_sides - U-127 / BE-138 (Chuze FINAL5, 4-nov): CB_BOTH_SIDES. Un type que imprime board en las dos caras\n(\'- BOTH SIDES\') y un wall con UNA sola cara con board = FAIL (el caso de los 7 walls tipo A de Chuze FINAL5); con las\ndos caras = PASS; capas impresas (2) y una cara con 1 capa = FAIL; la cara END no cuenta como lado; una cara faltante con\nboard_none_reason que cita N/HOJA = AMBER."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport chequeos_biblioteca as CB\nfj = {"types": {"A3C": {"faces": [{"side": "each side", "layers": None, "board": \'5/8" GYP BD - BOTH SIDES\'}], "sources": {"board": "A/A301"}},\n                "X6D": {"faces": [{"side": "each side", "layers": 2, "board": \'5/8" TYPE X GYP BD\'}], "sources": {"board": "X/A301"}}}}\nf = lambda side, lay=1: {"side": side, "board": "5/8 type X", "layers": lay, "height_ft": 10}\nuna = {"walls": [{"id": "W1", "tag": "A3C", "element": "wall", "faces": [f("A"), f("END")]}]}\nr = CB.both_sides(CB.B(canon=una, fichas=fj))\nassert r[0] == "FAIL" and "W1" in r[1][1], r\ndos = {"walls": [{"id": "W1", "tag": "A3C", "element": "wall", "faces": [f("A"), f("B")]}]}\nassert CB.both_sides(CB.B(canon=dos, fichas=fj))[0] == "PASS"\ncapa = {"walls": [{"id": "W2", "tag": "X6D", "element": "wall", "faces": [f("A", 2), f("B", 1)]}]}\nr = CB.both_sides(CB.B(canon=capa, fichas=fj))\nassert r[0] == "FAIL" and "capa" in " ".join(r[1]), r\nmot = {"walls": [{"id": "W3", "tag": "A3C", "element": "wall",\n                  "faces": [f("A"), {"side": "B", "board": None, "board_none_reason": "face against existing CMU, 3/A501"}]}]}\nassert CB.both_sides(CB.B(canon=mot, fichas=fj))[0] == "AMBER"\nassert CB.both_sides(CB.B(canon=una, fichas=None))[0] == "FAIL"     # sin lectura independiente no se puede probar\nprint("test_both_sides OK")\n'

# U-130 (comparativa con el banco, 4-nov) CE_COMPARATIVA_BANCO: test_banco · banco_md · ce_comparativa_banco
FUENTES['test_banco.py'] = '#!/usr/bin/env python3\n"""test_banco - U-130 (usuario 1-nov \'haz la comparativa con el mejor que tenemos\', compuerta 4-nov): compuerta_entrega.py\nbanco -> COMPARATIVA_BANCO.md; una familia fuera del rango del banco (por LF de partition) queda OUT OF RANGE y\nCE_COMPARATIVA_BANCO falla hasta que README_REVIEW.md la explica en \'Bank comparison\'; sin el .md = FAIL; .md de otro Excel = FAIL."""\nimport os, sys, tempfile, types\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport openpyxl\nimport compuerta_entrega as CE\nd = tempfile.mkdtemp()\ndef xl(nm, lf, stud, board, sf_piso=None):\n    wb = openpyxl.Workbook(); ws = wb.active; ws.title = "Inputs"\n    if sf_piso:\n        ws.append(["Total SF", f"{sf_piso:,} SF gross", "G-001"])\n    pt = wb.create_sheet("Partition Takeoff")\n    for _ in range(4):\n        pt.append(["h"])\n    pt.append(["TYPE A"]); pt.append(["A #1", "W1", lf, 10, 1, "3-5/8\\"", 16, board, "x", "A/A1", "[DERIVED]"])\n    ms = wb.create_sheet("Material Summary"); ms.append(["t"]); ms.append(["t"]); ms.append(["Material", "Unit", "Net"])\n    ms.append(["3-5/8\\" metal stud", "LF", stud]); ms.append(["5/8\\" gypsum board, Type X", "SF", board])\n    ms.append(["Demolition - gypsum board and metal stud framing", "SF", 99999])\n    p = os.path.join(d, nm); wb.save(p); return p\nr1 = xl("r1.xlsx", 100, 1000, 2000, 5000); r2 = xl("r2.xlsx", 200, 2400, 4400)\npx = xl("p.xlsx", 100, 9000, 2100, 6000)          # studs 90 / LF vs banco 10–12 -> OUT OF RANGE; board dentro; demo no cuenta\nmd = os.path.join(d, "COMPARATIVA_BANCO.md")\nfuera = CE.banco_md(px, [("R1", r1), ("R2", r2)], md)\nassert fuera == ["Studs"], fuera\nassert "Gypsum / cement board | SF | 2,100.00" in open(md).read()\nrd = os.path.join(d, "README_REVIEW.md")\nc = types.SimpleNamespace(w=d, excel=px, readme=rd)\nopen(rd, "w").write("# x\\n")\nassert CE.ce_comparativa_banco(c)[0] == "FAIL"\nopen(rd, "w").write("# x\\n## Bank comparison\\n- Studs: 12\\" o.c. structural studs on 22\' walls (RFI-S01).\\n")\nassert CE.ce_comparativa_banco(c)[0] == "PASS", CE.ce_comparativa_banco(c)\nc2 = types.SimpleNamespace(w=d, excel=r1, readme=rd)\nassert CE.ce_comparativa_banco(c2)[0] == "FAIL"            # .md de otro Excel\nos.remove(md)\nassert CE.ce_comparativa_banco(c)[0] == "FAIL"\nprint("test_banco OK")\n'

# R80f.42 (Chuze FINAL7, 4-nov) subir_entrega retoma una subida cortada: test_subida_retoma
FUENTES['test_subida_retoma.py'] = '#!/usr/bin/env python3\n"""test_subida_retoma - R80f.42 (Chuze FINAL7, 4-nov): una subida cortada por un error 5xx de Drive se RETOMA con\nsubir_entrega.py: el archivo que ya está en la carpeta destino con el mismo nombre y tamaño se salta; mismo nombre con otro\ntamaño = SUBIDA BLOQUEADA (nunca se sobrescribe). Sin el arreglo, la segunda corrida chocaba con \'put\' (archivo ya existe)."""\nimport json, os, subprocess, sys, tempfile\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport compuerta_entrega as CE\nimport test_compuerta_entrega as TC\nw = TC.workdir()\nTC.entrega_ok(w)\nya = sorted(os.path.join(r, f) for r, _, fs in os.walk(os.path.join(w, "FINAL_FOR_REVIEW")) for f in fs)\nuno = next(p for p in ya if p.endswith("README_REVIEW.md"))\ndef fake(tam):\n    d = tempfile.mkdtemp(prefix="fake_gd2_"); p = os.path.join(d, "gd.py"); log = os.path.join(d, "log.txt")\n    open(p, "w").write(\n        "import sys, json\\n"\n        f"open({log!r}, \'a\').write(\' \'.join(sys.argv[1:]) + \'\\\\n\')\\n"\n        "c = sys.argv[1]\\n"\n        "if c == \'list\' and sys.argv[2] == \'FOLDER123\':\\n    print(json.dumps({\'id\': \'FOLDER123\', \'name\': \'Proyecto X\'}))\\n"\n        f"elif c == \'list\' and sys.argv[2] == \'NEW_FINAL_FOR_REVIEW\':\\n    print(json.dumps({{\'id\': \'F1\', \'name\': \'README_REVIEW.md\', \'size\': \'{tam}\'}}))\\n"\n        f"elif c == \'list\' and sys.argv[2] == {CE.DRIVE_RAIZ!r}:\\n    print(json.dumps({{\'id\': \'FOLDER123\', \'name\': \'Proyecto X\'}}))\\n"\n        "elif c == \'mkdir\':\\n    print(\'NEW_\' + sys.argv[3])\\n"\n        "elif c == \'put\':\\n    print(\'OK uploaded \' + sys.argv[2])\\n")\n    return p, log\ngd, log = fake(os.path.getsize(uno))\nr = subprocess.run([sys.executable, "-I", os.path.join(CE.AQUI, "subir_entrega.py"), w], capture_output=True, text=True,\n                   env=dict(os.environ, GDRIVE_FETCH=gd))\nassert r.returncode == 0, r.stdout + r.stderr\nL = open(log).read()\nassert "put " + uno not in L and L.count("put ") == len(ya) - 1, L\ns = json.load(open(os.path.join(w, "SUBIDA_OK.json")))\nassert any("YA SUBIDO" in x["salida"] for x in s["subidos"]), s["subidos"]\ngd, log = fake(1)\nr = subprocess.run([sys.executable, "-I", os.path.join(CE.AQUI, "subir_entrega.py"), w], capture_output=True, text=True,\n                   env=dict(os.environ, GDRIVE_FETCH=gd))\nassert r.returncode == 1 and "otro tamaño" in r.stdout, r.stdout + r.stderr\nprint("test_subida_retoma OK")\n'

# R80f.43 / BE-141 (Chuze FINAL7 audit U-138, 4-nov) scope / Inputs / README figures by program: test_cifras_texto · cifras_texto · resolver_cifras
FUENTES['test_cifras_texto.py'] = '#!/usr/bin/env python3\n"""test_cifras_texto - R80f.43 / BE-141 (Chuze FINAL7 adversarial audit U-138, 4-nov): a material figure typed in the Scope\nChecklist that does not match its Material Summary row = FAIL (ALC-07 Type X 58,393.09 vs 57,241.60; ALC-08 27,973.17 vs\nthe EX- rows 26,818.18); the program placeholders {{MS:...}} / {{EX:board_sf}} write the real value at build time."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport chequeos_biblioteca as CB\nimport plantilla_excel as PE\nms = [(\'5/8" gypsum board, Type X\', 57241.6), (\'5/8" gypsum board, Type X MR (MOISTURE RESISTANT)\', 5831.23),\n      (\'Bottom track 3-5/8" - per source\', 100.0), (\'Bottom track 2-1/2"\', 4.77)]\nviejo = \'Quantified per face: 5/8" Type X 58,393.09 SF, 5/8" MR 5,483.88 SF\'\nex_viejo = \'get the full face replaced: 27,973.17 SF inside the Type X row\'\ne = CB.cifras_texto_err([("Scope Checklist!D8", viejo), ("Scope Checklist!D9", ex_viejo)], ms, 26818.18)\nassert len(e) == 3 and any("58,393.09" in x for x in e) and any("26,818.18" in x for x in e), e\nassert CB.cifras_texto_err([("x", \'5/8" Type X 57,241.60 SF, 5/8" MR 5,831.23 SF; 26,818.18 SF inside the Type X row\')], ms, 26818.18) == []\nassert CB.cifras_texto_err([("x", \'bottom track 104.77 LF; 2-1/2" bottom track 4.77 LF\')], ms) == []   # a row of one size is not the total\n# resolver_cifras: the placeholders take the value of the Material Summary / existing walls at build time\nd = {"materials": [{"material": m, "net": v} for m, v in ms], "existing_walls": [{"board_sf": 20000.0}, {"board_sf": 6818.18}]}\nt = PE.resolver_cifras(\'5/8" Type X {{MS:=5/8" gypsum board, Type X}} SF; {{EX:board_sf}} SF inside the Type X row; \'\n                       \'bottom track {{MS:Bottom track}} LF\', d)\nassert t == \'5/8" Type X 57,241.60 SF; 26,818.18 SF inside the Type X row; bottom track 104.77 LF\', t\nassert CB.cifras_texto_err([("x", t)], ms, 26818.18) == []\ntry:\n    PE.resolver_cifras("{{MS:no such row}}", d); raise AssertionError("an unknown row must not resolve")\nexcept ValueError:\n    pass\n# gate check on the delivered Excel cells\nb = CB.B(canon={}, ms=[{"fila": 4, "material": m, "net": v} for m, v in ms], pt=[{"wall": "EX-01", "board": 26818.18}],\n         celdas=[("Scope Checklist", "D8", viejo)], docs={})\nassert CB.cifras_texto(b)[0] == "FAIL"\nb.celdas = [("Scope Checklist", "D8", \'5/8" Type X 57,241.60 SF\')]\nassert CB.cifras_texto(b)[0] == "PASS"\nprint("test_cifras_texto OK")\n'

# R80f.44 / BE-142 (Chuze FINAL8 v40 gate, 4-nov) U-037 ONE WALL ONCE (tags_descartados / tag_ids): test_u037_duenos · u_037
FUENTES['test_u037_duenos.py'] = '#!/usr/bin/env python3\n"""test_u037_duenos - R80f.44 / BE-142 (Chuze FINAL8 v40 gate, 4-nov): ONE WALL ONCE. A tag on A101 whose wall is shown and\ncounted on the enlarged plan (canon tags_descartados with motive, or a wall of another sheet that owns it in tag_ids) is not a\nmissing wall; a tag with no owner and no motive still FAILS."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport chequeos_biblioteca as CB\ninv = [{"type": "A3C", "sheet": "A101", "kind": "partition_tag", "id": "PT0001"},\n       {"type": "A3C", "sheet": "A421", "kind": "partition_tag", "id": "PT0002"}]\nw = [{"id": "A-A421-1", "tag": "A3C", "sheet": "A421", "tag_ids": ["PT0002"]}]\nr = CB.u_037(CB.B(canon={"walls": w}, inventario=list(inv)))\nassert r[0] == "FAIL" and "A101" in " ".join(r[1]), r          # the original error: A101 tag, no wall on A101\ndesc = [{"id": "PT0001", "motivo": "shown on enlarged plan A421 (counted there)"}]\nassert CB.u_037(CB.B(canon={"walls": w, "tags_descartados": desc}, inventario=list(inv)))[0] == "PASS"\nw2 = [dict(w[0], tag_ids=["PT0002", "PT0001"])]                   # the enlarged-plan wall owns the A101 tag\nassert CB.u_037(CB.B(canon={"walls": w2}, inventario=list(inv)))[0] == "PASS"\nassert CB.u_037(CB.B(canon={"walls": w, "tags_descartados": [{"id": "PT0001", "motivo": "x"}]}, inventario=list(inv)))[0] == "FAIL"\nprint("test_u037_duenos OK")\n'

for nombre, src in FUENTES.items():
    p = os.path.join(AQUI, '_tmp_' + nombre)
    open(p, 'w').write(src)
    try:
        runpy.run_path(p, run_name='__main__')
    except SystemExit as e:
        if e.code not in (None, 0):
            raise SystemExit(f'{nombre}: FALLA ({e.code})')
    finally:
        os.remove(p)
